<?php
require_once 'includes/config.php'; require_teacher();
$tid=current_teacher_id(); $message=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $action=$_POST['action']??'';
  if($action==='apply'){
   $type=(int)($_POST['leave_type_id']??0);$start=(string)($_POST['start_date']??'');$end=(string)($_POST['end_date']??'');$remark=trim((string)($_POST['teacher_remark']??''));
   if(!$type||!$start||!$end||$end<$start||$remark==='')throw new RuntimeException('Select leave type, valid dates and provide a remark.');
   $days=(new DateTimeImmutable($start))->diff(new DateTimeImmutable($end))->days+1;
   $q=$dbh->prepare("SELECT id FROM srms_teacher_leaves WHERE teacher_id=:t AND status IN ('pending','approved') AND NOT(end_date<:s OR start_date>:e)");$q->execute([':t'=>$tid,':s'=>$start,':e'=>$end]);if($q->fetchColumn())throw new RuntimeException('These dates overlap an existing pending or approved leave.');
   $q=$dbh->prepare("INSERT INTO srms_teacher_leaves(teacher_id,leave_type_id,start_date,end_date,days_requested,teacher_remark,status) VALUES(:t,:l,:s,:e,:d,:r,'pending')");$q->execute([':t'=>$tid,':l'=>$type,':s'=>$start,':e'=>$end,':d'=>$days,':r'=>$remark]);audit_log($dbh,'TEACHER_LEAVE_APPLY','Teacher '.$tid.' requested '.$days.' days');$message='Leave request submitted for approval.';
  }elseif($action==='cancel'){
   $id=(int)($_POST['id']??0);$q=$dbh->prepare("UPDATE srms_teacher_leaves SET status='cancelled',updated_at=NOW() WHERE id=:id AND teacher_id=:t AND status='pending'");$q->execute([':id'=>$id,':t'=>$tid]);if(!$q->rowCount())throw new RuntimeException('Only your pending requests can be cancelled.');$message='Request cancelled.';
  }
 }catch(Throwable $e){$error=$e instanceof PDOException?'Unable to save leave request. Check that Phase 14 migration is installed.':$e->getMessage();}
}
$types=$dbh->query('SELECT id,leave_name,annual_days FROM srms_leave_types WHERE is_active=1 ORDER BY leave_name')->fetchAll();
$q=$dbh->prepare("SELECT l.*,t.leave_name,a.UserName reviewer FROM srms_teacher_leaves l JOIN srms_leave_types t ON t.id=l.leave_type_id LEFT JOIN admin a ON a.id=l.reviewed_by WHERE l.teacher_id=:t ORDER BY l.created_at DESC");$q->execute([':t'=>$tid]);$leaves=$q->fetchAll();
$year=(int)($_GET['year']??date('Y'));if($year<2000||$year>2100)$year=(int)date('Y');$balances=[];foreach($types as $t){$q=$dbh->prepare("SELECT COALESCE(SUM(days_requested),0) FROM srms_teacher_leaves WHERE teacher_id=:t AND leave_type_id=:l AND status='approved' AND YEAR(start_date)=:y");$q->execute([':t'=>$tid,':l'=>$t['id'],':y'=>$year]);$taken=(float)$q->fetchColumn();$balances[]=['name'=>$t['leave_name'],'total'=>(float)$t['annual_days'],'taken'=>$taken,'balance'=>max(0,(float)$t['annual_days']-$taken)];}
$teacherName=$_SESSION['teacher_name']??'Teacher';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Leave | <?php echo e(srms_school_name());?></title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/srms-responsive.css"><style>.leave-card{border:1px solid #e4eaf2;border-radius:12px;padding:18px;margin-bottom:16px;background:#fff}.leave-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}@media(max-width:650px){.leave-grid{grid-template-columns:1fr}.table td,.table th{white-space:normal!important}}</style></head><body><nav class="navbar navbar-default srms-mobile-nav"><div class="container-fluid"><a class="navbar-brand" href="teacher-dashboard.php"><?php echo e(srms_school_name());?></a><p class="navbar-text pull-right"><img src="profile-photo.php?type=teacher&id=<?php echo $tid;?>" alt="" width="30" height="30" style="border-radius:50%;object-fit:cover" onerror="this.style.display='none'"> <?php echo e($teacherName);?> · <a href="teacher-logout.php">Logout</a></p></div></nav><main class="container-fluid srms-page"><div class="srms-toolbar"><a class="btn btn-default" href="teacher-dashboard.php">← Dashboard</a></div><h2>My Leave</h2><p class="text-muted">Annual leave allowances for <?php echo $year;?>. Approved requests count toward leave taken.</p><?php if($message):?><div class="alert alert-success"><?php echo e($message);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?>
<form method="get" class="form-inline" style="margin:10px 0"><label for="leave-year">Balance year </label> <select id="leave-year" name="year" class="form-control"><?php for($yy=(int)date('Y')+1;$yy>=(int)date('Y')-5;$yy--):?><option value="<?php echo $yy;?>" <?php echo $year===$yy?'selected':'';?>><?php echo $yy;?></option><?php endfor;?></select> <button class="btn btn-default">View year</button></form><div class="leave-grid"><?php foreach($balances as $b):?><div class="leave-card"><strong><?php echo e($b['name']);?></strong><div class="row"><div class="col-xs-4"><small>Total</small><h3><?php echo $b['total'];?></h3></div><div class="col-xs-4"><small>Taken</small><h3><?php echo $b['taken'];?></h3></div><div class="col-xs-4"><small>Balance</small><h3><?php echo $b['balance'];?></h3></div></div></div><?php endforeach;?></div>
<div class="panel panel-primary"><div class="panel-heading">Apply for leave</div><div class="panel-body"><form method="post"><input type="hidden" name="csrf_token" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="apply"><div class="row"><div class="col-sm-4 form-group"><label>Leave type</label><select name="leave_type_id" class="form-control" required><option value="">Choose leave type</option><?php foreach($types as $t):?><option value="<?php echo (int)$t['id'];?>"><?php echo e($t['leave_name']);?> (<?php echo e($t['annual_days']);?> days/year)</option><?php endforeach;?></select></div><div class="col-sm-3 form-group"><label>From</label><input type="date" name="start_date" class="form-control" required></div><div class="col-sm-3 form-group"><label>To</label><input type="date" name="end_date" class="form-control" required></div><div class="col-sm-12 form-group"><label>Remark / reason</label><textarea name="teacher_remark" class="form-control" rows="3" maxlength="2000" required></textarea></div></div><button class="btn btn-primary">Submit for approval</button></form></div></div>
<div class="panel panel-default"><div class="panel-heading">My requests and decisions</div><div class="panel-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Type</th><th>Dates</th><th>Days</th><th>Status</th><th>My remark</th><th>Admin remark</th><th>Action</th></tr></thead><tbody><?php foreach($leaves as $l):?><tr><td><?php echo e($l['leave_name']);?></td><td><?php echo e($l['start_date'].' – '.$l['end_date']);?></td><td><?php echo e($l['days_requested']);?></td><td><span class="label label-<?php echo ['approved'=>'success','rejected'=>'danger','cancelled'=>'default','pending'=>'warning'][$l['status']]??'default';?>"><?php echo e(ucfirst($l['status']));?></span></td><td><?php echo e($l['teacher_remark']);?></td><td><?php echo e($l['admin_remark']??'—');?></td><td><?php if($l['status']==='pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?php echo (int)$l['id'];?>"><button class="btn btn-xs btn-default">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$leaves):?><tr><td colspan="7">No leave requests yet.</td></tr><?php endif;?></tbody></table></div></div></div></main></body></html>